import json
def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)];comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                stack=[(i,j)];seen[i][j]=True;comp=[]
                while stack:
                    y,x=stack.pop();comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx] and not seen[ny][nx]:
                                seen[ny][nx]=True;stack.append((ny,nx))
                comps.append(comp)
    comps.sort(key=len,reverse=True)
    pat=comps[0]
    pivot=[p for p in pat if g[p[0]][p[1]]==5][0]
    markers=[c[0] for c in comps[1:] if g[c[0][0]][c[0][1]]==5]
    for (my,mx) in markers:
        out[my][mx]=0
        for (y,x) in pat:
            v=g[y][x]
            if v==5: continue
            ny,nx=my-pivot[0]+y,mx-pivot[1]+x
            if 0<=ny<H and 0<=nx<W: out[ny][nx]=v
    return out
